evaluate_cox <- function(subjects,vectors,beta) {
  p <- length(beta)
  predictors <- vapply(vectors,function(x) total(beta*x),numeric(1))
  risks <- exp(predictors)
  order <- order(-vapply(subjects,`[[`,integer(1),"time"),vapply(subjects,`[[`,integer(1),"id"))
  s0 <- likelihood <- 0
  s1 <- score <- numeric(p)
  s2 <- information <- matrix(0,p,p)
  event_sums <- list()
  position <- 1L
  while (position <= length(order)) {
    time <- subjects[[order[position]]]$time
    stop <- position
    while (stop <= length(order) && subjects[[order[stop]]]$time == time) stop <- stop+1L
    indices <- order[seq.int(position,stop-1L)]
    for (i in indices) {
      risk <- risks[i]
      x <- vectors[[i]]
      s0 <- s0+risk
      for (c in seq_len(p)) {
        s1[c] <- s1[c]+risk*x[c]
        for (d in seq_len(p)) s2[c,d] <- s2[c,d]+risk*x[c]*x[d]
      }
    }
    events <- indices[vapply(indices,function(i) subjects[[i]]$event == 1L,logical(1))]
    if (length(events)) {
      n <- length(events)
      likelihood <- likelihood+(total(predictors[events])-n*log(s0))
      for (c in seq_len(p)) {
        score[c] <- score[c]+(sum(vapply(events,function(i) vectors[[i]][c],integer(1)))-n*s1[c]/s0)
        for (d in seq_len(p)) information[c,d] <- information[c,d]+n*(s2[c,d]/s0-(s1[c]/s0)*(s1[d]/s0))
      }
      event_sums[[as.character(time)]] <- list(s0=s0,s1=s1,events=n)
    }
    position <- stop
  }
  list(loglik=likelihood,score=score,information=information,predictors=predictors,event_sums=event_sums)
}
fit_cox <- function(subjects,vectors) {
  beta <- numeric(length(vectors[[1L]]))
  null <- evaluate_cox(subjects,vectors,beta)
  current <- null
  iterations <- list()
  for (iteration in seq_len(25L)) {
    change <- solve_system(current$information,current$score)
    beta <- beta+change
    iterations[[iteration]] <- list(number=iteration,loglik=current$loglik,beta=beta)
    current <- evaluate_cox(subjects,vectors,beta)
  }
  list(beta=beta,null=null,final=current,iterations=iterations)
}

WEIGHTS <- c("logrank","gehan_wilcoxon","tarone_ware")
empty_totals <- function(groups) {
  n <- length(groups)
  list(groups=groups,events=numeric(n),observed=numeric(n),expected=numeric(n),covariance=matrix(0,n,n))
}
weighted_totals <- function(subjects,groups,weight,population) {
  result <- empty_totals(groups)
  collections <- lapply(groups,function(group) Filter(function(s) s$group == group,subjects))
  times <- sort(unique(vapply(Filter(function(s) s$event == 1L,subjects),`[[`,integer(1),"time")))
  for (time in times) {
    risk <- vapply(
        collections,
        function(rows) sum(vapply(rows,function(s) s$time >= time,logical(1))),
        numeric(1)
    )
    deaths <- vapply(
        collections,
        function(rows) sum(vapply(rows,function(s) s$time == time && s$event == 1L,logical(1))),
        numeric(1)
    )
    n <- sum(risk)
    d <- sum(deaths)
    value <- if (weight == "logrank") 1 else if (weight == "gehan_wilcoxon") n/population else sqrt(n/population)
    for (h in seq_along(groups)) {
      result$events[h] <- result$events[h]+deaths[h]
      result$observed[h] <- result$observed[h]+value*deaths[h]
      result$expected[h] <- result$expected[h]+value*(d*risk[h]/n)
      if (n < 2L) next
      factor <- value*value*(d*(n-d)/((n-1)*n*n))
      for (l in seq_along(groups)) {
        multiple <- if (h == l) risk[h]*(n-risk[h]) else -(risk[h]*risk[l])
        result$covariance[h,l] <- result$covariance[h,l]+factor*multiple
      }
    }
  }
  result
}
finish_test <- function(result) {
  df <- length(result$groups)-1L
  indices <- seq_len(df)
  difference <- result$observed[indices]-result$expected[indices]
  solution <- solve_system(result$covariance[indices,indices,drop=FALSE],difference)
  result$statistic <- total(difference*solution)
  result$degrees <- df
  result$p <- chi_square_p(result$statistic,df)
  result
}
weighted_test <- function(subjects,groups,weight,population) finish_test(weighted_totals(
    subjects,
    groups,
    weight,
    population
))
combine_strata <- function(strata,groups) {
  result <- empty_totals(groups)
  for (stratum in strata) {
    result$events <- result$events+stratum$events
    result$observed <- result$observed+stratum$observed
    result$expected <- result$expected+stratum$expected
    result$covariance <- result$covariance+stratum$covariance
  }
  finish_test(result)
}

